package resource

import (
	"crypto/rand"
	"encoding/hex"
	"errors"
	"fmt"
	"strings"
)

// ResourceID is a canonical UUID generated by Machinarchy. It is independent
// of database sequences and remote host addresses.
type ResourceID string

func NewResourceID() (ResourceID, error) {
	var value [16]byte
	if _, err := rand.Read(value[:]); err != nil {
		return "", fmt.Errorf("generate resource ID: %w", err)
	}
	value[6] = (value[6] & 0x0f) | 0x40
	value[8] = (value[8] & 0x3f) | 0x80
	encoded := hex.EncodeToString(value[:])
	return ResourceID(encoded[:8] + "-" + encoded[8:12] + "-" + encoded[12:16] + "-" + encoded[16:20] + "-" + encoded[20:]), nil
}

func ParseResourceID(value string) (ResourceID, error) {
	value = strings.ToLower(strings.TrimSpace(value))
	if len(value) != 36 || value[8] != '-' || value[13] != '-' || value[18] != '-' || value[23] != '-' {
		return "", errors.New("resource ID must be a canonical UUID")
	}
	compact := strings.ReplaceAll(value, "-", "")
	if _, err := hex.DecodeString(compact); err != nil {
		return "", errors.New("resource ID must be a canonical UUID")
	}
	return ResourceID(value), nil
}

func (id ResourceID) Validate() error {
	parsed, err := ParseResourceID(string(id))
	if err != nil || parsed != id {
		return errors.New("resource ID must be a canonical lowercase UUID")
	}
	return nil
}
